mapper.select:
select * from `student`


        AND ID = #{ID}


        AND team_ID = #{team_ID}


        AND name like concat('%',#{name},'%')


        AND role = #{role}


        AND tele like concat('%',#{tele},'%')


        AND gender = #{gender}


        AND age = #{age}


order by ID asc

mapper.update:
update `student`
set team_ID = #{team_ID}, name = #{name}, role = #{role}, tele = #{tele},
    gender = #{gender}, age = #{age}
where ID = #{ID}
